  ui_story_5060_50600101_83_dialog_content = "ฉันอยากถามมานานแล้ว แต่ \"<color=#FFB400>อิคลิพไซท์</color>\" คือสัตว์ประหลาดชนิดหนึ่งใช่ไหม?",
