  ui_story_5060_50600201_9_dialog_content = "ฮา—",
  ui_story_5060_50600201_10_dialog_content = "เดี๋ยวสิ, คุณไม่ได้ตกลงมาต่อสู้หนึ่งต่อหนึ่งหรือเปล่า? คุณจะไฟฟ้าดูดตัวประกันด้วยหรือเปล่า!?",
  ui_story_5060_50600201_11_dialog_content = "ฉันไม่รังเกียจเลยจริง ๆ นะ!",
  ui_story_5060_50600201_12_dialog_content = "ฉันรอดชีวิตจากการตกเครื่องบิน, ฝนตกหนัก, การโจมตีทางจิต, บาดเจ็บจากเครื่องมือ, และแม้กระทั่งมีวัตถุต่างประเทศเข้าสู่ร่างกายของฉัน...",
  ui_story_5060_50600201_13_dialog_content = "หลังจากประสบประสบการณ์ทั้งหมดนั้น คุณคิดจริงๆ ว่าฉันกลัวไฟฟ้าช็อตเล็ก ๆ หรือเปล่า?!",
  ui_story_5060_50600201_14_dialog_content = "อะไรนะ? Caelestites มักจะไม่เข้าขั้นเสมอหรือ?",
  ui_story_5060_50600201_15_dialog_content = "ฮ่า ด้วยสภาพของพวกคุณตอนนี้ คุณไม่สามารถทำให้ Caelestite เสียเลือดเล็กน้อยแม้แต่นิดเดียว นอกจากนี้...",
  ui_story_5060_50600201_16_dialog_content = "เราไม่เคยขโมย<color=#FFB400>คอลเลกชัน</color>ที่คุณพูดถึง นี่ต้องเป็นความเข้าใจผิดประเภทหนึ่ง",
  ui_story_5060_50600201_17_dialog_content = "เลิกเถอะนะ พวกคุณก็ต้องกินด้วยใช่ไหม? ถ้าเรายังทำแบบนี้ต่อ อาหารกลับบ้านของฉันจะเย็นหมดแน่ๆ",
  ui_story_5060_50600201_18_dialog_content = "แต่... คุณก็เป็นคนเดียวที่อยู่ตอนที่ของหายไป! เราควรสงสัยใครอีกล่ะ?!",
  ui_story_5060_50600201_19_dialog_content = "หรือ... คุณก็สามารถเสนอจะจ่ายเงินให้ก็ได้นะ",
