  ui_story_5060_50600201_25_dialog_content = "เลยนะ ตอนนี้แกกำลังใส่ความผิดให้เด็กผู้หญิงตัวเล็ก ๆ นี่เหรอ? แกไม่อายหน้าจริง ๆ นะ",
